from lib import *
N=2
TITLE='המהפכה החוקתית'
SUM=[
h3('2.1 מה קרה ב-1992 ולמה זו "מהפכה"'),
p('במרץ 1992 חוקקה הכנסת שני חוקי יסוד שעניינם זכויות אדם: <b>חוק יסוד: כבוד האדם וחירותו</b> ו<b>חוק יסוד: חופש העיסוק</b> (שנחקק מחדש ב-1994 עם פסקת התגברות). לראשונה נכללו בחקיקה ישראלית זכויות יסוד לצד <b>פסקת הגבלה</b>, כלומר נוסחה המגדירה מתי מותר לפגוע בהן. במשך שנים לא הייתה ברורה משמעות החקיקה, עד שבית המשפט העליון קבע בשנת 1995, בפסק דין בנק המזרחי, שיש לה מעמד על-חוקי. הנשיא ברק כינה את השינוי "המהפכה החוקתית": ישראל עברה מעליונות הכנסת לעליונות החוקה.'),
box('case','בנק המזרחי המאוחד נ׳ מגדל כפר שיתופי (1995)','בנקים ובעלי נכסים תקפו את "חוק גל", שהסדיר את חובות המגזר החקלאי ופגע, לטענתם, בקניין הנושים. ההרכב המורחב (תשעה שופטים) קבע שחוקי היסוד הם בעלי מעמד חוקתי עליון, ושבית המשפט רשאי לפסול חוק רגיל שסותר אותם. העתירה נדחתה, כי הפגיעה בקניין עמדה בתנאי פסקת ההגבלה. מכאן נולד המבחן החוקתי בישראל.'),
h3('2.2 תורת שני הכובעים: מקור העליונות'),
p('הבעיה המשפטית: חוק יסוד נחקק לרוב באותו הליך, ובאותו רוב, כמו חוק רגיל. מנין העליונות? תשובתו של ברק היא <b>תורת הסמכות המכוננת</b>: הכנסת חובשת שני כובעים. כאשר היא מחוקקת חוק יסוד, היא פועלת כ<b>רשות מכוננת</b> (יוצרת חוקה), וכאשר היא מחוקקת חוק רגיל, היא פועלת כ<b>רשות מחוקקת</b>. נורמה שנוצרה בכובע המכונן גוברת על נורמה שנוצרה בכובע המחוקק, בדיוק כפי שחוקה גוברת על חוק. הסמכות המכוננת מבוססת על כך שהכנסת הראשונה נבחרה גם כדי לנסח חוקה, והיא עברה ממנה לכנסות הבאות.'),
box('def','סמכות מכוננת','הסמכות ליצור חוקה ולתקן אותה. לפי ברק, היא נתונה לכנסת כשהיא מחוקקת "חוק יסוד", ושונה במהותה מהסמכות לחוקק חוק רגיל.'),
h3('2.3 שלוש הגישות בבנק המזרחי'),
tbl(['שופט','עיקר הגישה'],[
['הנשיא ברק','יש סמכות מכוננת נפרדת; חוקי היסוד עליונים מכוחה (שני הכובעים). זו הגישה שהתקבלה כגישה המובילה.'],
['הנשיא שמגר','מקבל את עליונות חוקי היסוד ואת סמכות הביקורת, אך עם דגשים משלו בנוגע למקור הסמכות; מדגיש שהכנסת עצמה ביקשה לעגן זכויות.'],
['השופט חשין','סבור שיש לגלות זהירות, מפקפק ביכולת לקבוע שהכנסת "נעשתה" רשות מכוננת, ומדגיש את הצורך בחקיקה מפורשת של חוקה.']]),
p('למבחן אין צורך לשנן את הניואנסים של כל שופט. חשוב לזכור את התוצאה (מעמד על-חוקי, סמכות פסילה) ואת המחלוקת המושגית על מקור הסמכות. הביקורת על ברק היא שהוא "יצר" חוקה בלי החלטה מפורשת של העם או של אסיפה מכוננת, ושהכנסת לא ידעה שהיא חובשת כובע מכונן כשחוקקה את חוקי 1992.'),
h3('2.4 מה נבחן אחרי המהפכה'),
p('המהפכה לא ביטלה את עליונות הכנסת באופן מלא. ראשית, חוק רגיל שפוגע בזכות יהיה תקף אם עמד בתנאי פסקת ההגבלה. שנית, הוראת <b>שמירת דינים</b> (ס׳ 10 לחוק יסוד: כבוד האדם) מגינה על חקיקה שקדמה לחוק. שלישית, בחוק יסוד: חופש העיסוק קיימת <b>פסקת התגברות</b> המאפשרת לכנסת לגבור בחקיקה ברוב. רביעית, בית המשפט נוקט ריסון, ורובם המכריע של החוקים שנבחנו נותרו בתוקף. פסילת חוק היא נדירה, והראשונה הגיעה רק ב-2009 (הפרטת בתי הסוהר).'),
ul('<b>שלב א:</b> האם החוק פוגע בזכות חוקתית (פרשנות הזכות).','<b>שלב ב:</b> האם הפגיעה עומדת בפסקת ההגבלה.','<b>שלב ג:</b> הסעד, אם הפגיעה אינה כדין.'),
box('warn','מלכודות נפוצות',['לטעון שבנק המזרחי פסל את חוק גל - הוא <b>לא</b> נפסל. ההלכה נקבעה אגב דחיית העתירה.','לבלבל בין "שני הכובעים" (מקור העליונות) לבין "שני החוקים" (1992) - אלה מושגים שונים.','לטעון שהמהפכה נעשתה בחוק יסוד - היא נעשתה בפסיקה, בפרשנות החוקים.']),
h3('2.5 חוקי היסוד מאז: התפתחויות'),
p('בעשורים שאחרי בנק המזרחי פסל בג"ץ חוקים בודדים בלבד. נחקק גם חוק יסוד: הלאום (2018), ועלתה שאלה אם לבית המשפט סמכות לבקר חוקי יסוד עצמם. בשנת 2024 (בג"ץ 5658/23) פסל בית המשפט תיקון לחוק יסוד: השפיטה, והכריע ברוב שיש לו סמכות לבקר חוק יסוד במקרים קיצוניים של שימוש לרעה בסמכות המכוננת. הנושא נדון בפרק הבא.'),
box('tip','שלד לתשובה על "המהפכה החוקתית"',['הרקע: מודל ווסטמינסטר, החלטת הררי, חוקי 1992.','הלכת בנק המזרחי: עליונות ומקור הסמכות (שני כובעים).','ההסתייגויות: חשין, ביקורת על "מהפכה שיפוטית".','התוצאה: מבחן חוקתי מבוסס פסקת הגבלה, ריסון בפועל.']),
box('ex','תרגיל פתור','חוק רגיל מגביל בקשות לרישיון עיסוק, ובעל עסק טוען שנפגע חופש העיסוק. מה השלב הראשון? <b>פתרון:</b> לבדוק אם החוק פוגע בזכות המוגנת בחוק היסוד (שלב א), ואם כן, האם הוא בחוק, לתכלית ראויה ובמידתיות (שלב ב). רק אם נכשל - הסעד.'),
box('key','סיכום הפרק',['1992: חוקי זכויות עם פסקת הגבלה; 1995: בנק המזרחי.','תורת שני הכובעים (ברק): מכונן מול מחוקק.','שלוש גישות: ברק, שמגר, חשין.','המהפכה הותירה את הכנסת חזקה: מבחן חוקתי בעל שלבים ופסקאות שמירה והתגברות.'])
]
CASES=[
('ע"א 6821/93 בנק המזרחי המאוחד בע"מ נ׳ מגדל כפר שיתופי, פ"ד מט(4) 221 (1995)','בנקים תקפו את חוק גל להסדר חובות חקלאים בטענה לפגיעה בקניין. ההרכב המורחב דן בעליונות חוקי היסוד.','חוקי היסוד של 1992 הם בעלי מעמד על-חוקי, ובית המשפט רשאי לפסול חוק הסותר אותם. הנשיא ברק ביסס זאת על תורת שני הכובעים. העתירה נדחתה כי הפגיעה עמדה בפסקת ההגבלה. למבחן: ההלכה אינה בתוצאה (דחייה) אלא במעמד הנורמטיבי.'),
('בג"ץ 98/69 ברגמן נ׳ שר האוצר (1969)','חוק מימון מפלגות נתקבל ברוב רגיל על אף שריון ס׳ 4 לחוק יסוד: הכנסת.','הכנסת כבולה להוראות שריון בחוקי יסוד; חוק שנתקבל ללא הרוב הנדרש לא יחול. זה תקדים מוקדם לסמכות פסילה, ובו כבר הוכרה החקיקה החוקתית כחוק עליון לגבי הוראות משוריינות. למבחן: מבסס את ההבחנה בין חוק רגיל להוראה משוריינת.'),
('בג"ץ 2605/05 המרכז האקדמי למשפט ולעסקים נ׳ שר האוצר (2009)','תיקון לפקודת בתי הסוהר איפשר להעביר ניהול בית סוהר לחברה פרטית. עתירה טענה לפגיעה בכבוד ובחירות האסירים.','החוק נפסל, וזו הפעם הראשונה שבה בית המשפט פסל חוק רגיל של הכנסת מחמת סתירה לחוק יסוד בתחום שלא נשמרו בו דינים. נקבע שהעברת סמכויות כפייה לגורם פרטי הפועל מתוך מניע רווח פוגעת בכבוד ובחירות באופן שאינו עומד בפסקת ההגבלה. למבחן: הדוגמה הקלאסית לפסילה בפועל.'),
('בג"ץ 5658/23 התנועה למען איכות השלטון ואח׳ נ׳ הכנסת (2024)','תיקון לחוק יסוד: השפיטה צמצם את עילת הסבירות כלפי החלטות הממשלה והשרים.','התיקון נפסל ברוב של 8 שופטים מול 7. הוכרעה סמכות בית המשפט לבקר חוק יסוד במקרים נדירים וקיצוניים של שימוש לרעה בסמכות המכוננת. פרטי הרוב בשאלת הסמכות ובשאלת הפסילה שונים. למבחן: ההלכה היא על עצם הסמכות לבקר חוקי יסוד, והיא קשורה לפרק מעמד חוקי היסוד.')
]
QS=[
Q('מה פירוש "המהפכה החוקתית" לפי הנשיא ברק?','מעבר מעליונות הכנסת לעליונות חוקי היסוד, עם ביקורת שיפוטית על חקיקה',['העברת הסמכות החוקתית מהכנסת לממשלה','ביטול הכנסת כרשות מחוקקת','חקיקת חוקה אחת מלאה בכנסת ה-12'],'המהפכה היא שינוי במעמד הנורמטיבי של חוקי היסוד: בג"ץ רשאי לפסול חוק רגיל. הכנסת לא בוטלה, ולא נכתבה חוקה שלמה, ולכן שלושת המסיחים מתארים תהליכים שלא אירעו.'),
Q('מהי תורת "שני הכובעים"?','הכנסת פועלת כרשות מכוננת וכרשות מחוקקת',['השופטים פועלים כמחוקקים וכשופטים','הממשלה מחוקקת ומבצעת','הנשיא פועל כראש מדינה וכראש ממשלה'],'התורה מבחינה בין שתי סמכויות של הכנסת, מכוננת ומחוקקת, ומהן נגזרת עליונות חוקי היסוד. שני המסיחים האחרים מתארים עירוב רשויות שאינו חלק מתורה זו.'),
Q('ב-1992 נחקקו חוק יסוד כבוד האדם וחירותו וחוק יסוד:','חופש העיסוק',['הלאום','משאל עם','מקרקעי ישראל'],'שני חוקי הזכויות של 1992 הם כבוד האדם וחופש העיסוק. חוק הלאום נחקק ב-2018, משאל עם ב-2014, ומקרקעי ישראל כבר ב-1960, ולכן אינם הזוג הנכון.'),
Q('בבנק המזרחי נדון בעיקר חוק:','גל להסדר חובות חקלאים',['טל לדחיית שירות','ההסדרים הכלכליים','יבוא בשר קפוא'],'בנק המזרחי עסק בחוק גל (הסדר חובות חקלאים) ובשאלת פגיעה בקניין הנושים. חוק טל נדון בשוויון, ויבוא בשר קפוא בחופש העיסוק ובפסקת ההתגברות.'),
Q('מה היה גורלו של חוק גל בבנק המזרחי?','נדחתה העתירה, כי הפגיעה עמדה בתנאי פסקת ההגבלה',['החוק נפסל מיד כי הוא סותר חוק יסוד','החוק נפסל חלקית בלבד','העתירה נדחתה כי אין לבית המשפט סמכות'],'ההלכה בדבר הסמכות נקבעה, אך החוק עצמו נותר בתוקף כי עמד בתנאי ההגבלה. המסיח האחרון הפוך: דווקא נקבע שיש סמכות, והחוק לא נפסל בכלל.'),
Q('מהי עמדת השופט חשין בבנק המזרחי בקצרה?','גישה מסויגת ומפקפקת בעצם קיומה של סמכות מכוננת נפרדת',['תמך במלואה בתורת שני הכובעים','טען שחוקי היסוד אינם עליונים כלל','הציע לבטל את חוקי היסוד של 1992'],'חשין הסתייג מהגישה המהפכנית וביקר את הקביעה שהכנסת פועלת כרשות מכוננת. הוא לא שלל את חוקי היסוד לגמרי, ולכן המסיחים האחרים מגזימים בכיוונים הפוכים.'),
Q('הפסילה הראשונה של חוק רגיל בשל סתירה לחוק יסוד נעשתה ב:','בג"ץ הפרטת בתי הסוהר',['בג"ץ בנק המזרחי','בג"ץ קול העם','בג"ץ ברגמן'],'בפרשת הפרטת בתי הסוהר (2009) נפסל לראשונה חוק רגיל בשל סתירה לחוק היסוד על כבוד האדם. בנק המזרחי הכיר בסמכות בלבד, וקול העם וברגמן קדמו למהפכה.'),
Q('מהי "פסקת ההגבלה"?','הוראה הקובעת מתי מותר לפגוע בזכות חוקתית',['הוראה האוסרת על כל פגיעה בזכות','הוראה המאפשרת לכנסת לגבור על בג"ץ','הוראה הקובעת את תקופת כהונת הכנסת'],'פסקת ההגבלה היא הנוסחה לפגיעה כדין בזכות. האיסור המוחלט אינו נכון, כי זכויות יחסיות; ההתגברות היא פסקה נפרדת בחוק העיסוק; ותקופת הכהונה שייכת לחוק יסוד: הכנסת.'),
Q('מה אומרת הביקורת העיקרית על "המהפכה החוקתית"?','שבית המשפט יצר חוקה בלי החלטה מפורשת של העם או של אסיפה מכוננת',['שהכנסת ביטלה את בית המשפט','שהחוקה האמריקאית נותרה בישראל','שהזכויות נשללו מהאזרחים'],'הביקורת עיקרה דמוקרטית ופרוצדורלית: חוקה "נוצרה" בפרשנות. המסיחים האחרים אינם קשורים לביקורת זו.'),
Q('לפי שיטת המהפכה, מה מעמד חוק רגיל הפוגע בזכות חוקתית ועומד בפסקת ההגבלה?','תקף',['בטל תמיד','בטל רק אם הוא נחקק לפני 1992','תקף רק אם הכנסת אישרה אותו פה אחד'],'זכויות אינן מוחלטות. פגיעה העומדת בתנאי פסקת ההגבלה היא פגיעה כדין, והחוק תקף. אין דרישה להסכמה פה אחד או להתחשב בתאריך החקיקה.'),
Q('מהו ההבדל בין סמכות מכוננת לסמכות מחוקקת?','מכוננת יוצרת חוקה ומחוקקת מחוקקת חוק רגיל',['מכוננת שייכת לבג"ץ ומחוקקת לכנסת','מכוננת חלה רק על תקנות','אין הבדל מעשי'],'ההבחנה ביסוד התורה היא בין יצירת נורמה חוקתית לבין חקיקה רגילה. הטענה שהמכוננת בידי בג"ץ שגויה, והקביעה שאין הבדל מעשי מחטיאה את הליבה.'),
Q('למה ההלכה בבנק המזרחי נחשבת "מהפכה" אף שהעתירה נדחתה?','כי נקבעה סמכות פסילה שלא הייתה קודם',['כי נפסל חוק רגיל','כי הכנסת התפזרה','כי בוטלה פסקת ההגבלה'],'המהפכה היא בהלכה על הסמכות, לא בתוצאה הקונקרטית. החוק לא נפסל, הכנסת לא התפזרה, ופסקת ההגבלה נותרה בתוקף.'),
Q('מה נקבע לגבי הרכב השופטים בבנק המזרחי?','הרכב מורחב של תשעה שופטים',['הרכב של שלושה שופטים','הרכב של שבעה שופטים בלבד','שופט יחיד'],'המעמד העקרוני של החלטה הצריך הרכב מורחב של תשעה שופטים. הרכב של שלושה או שופט יחיד אינם מתאימים לסוגיה בהיקף זה.'),
Q('איזו קביעה נכונה לגבי הוראת שמירת הדינים?','היא מגנה על חקיקה שקדמה לחוק היסוד',['היא פוסלת חקיקה ישנה','היא חלה על כל תיקון עתידי','היא מבטלת את פסקת ההגבלה'],'ס׳ 10 שומר על דינים שנחקקו לפני החוק, אך אינו מגן על חקיקה חדשה או על תיקון מאוחר. הוא לא פוסל חוקים ישנים ולא מבטל את ההגבלה.'),
Q('איזה מהבאים נכון לגבי בג"ץ 5658/23 (2024)?','נפסל תיקון לחוק יסוד: השפיטה שצמצם את עילת הסבירות',['נפסל חוק הלאום','נפסל חוק גל','נפסל חוק טל'],'בפרשה זו הכריע בית המשפט בחוק יסוד עצמו (תיקון לחוק יסוד: השפיטה). חוק גל נדון ב-1995, חוק טל בעניין שוויון, וחוק הלאום נדחה בעתירה אחרת.'),
Q('מה ההשלכה של הרשאה לבית המשפט לבקר חוק יסוד?','שגם חוק יסוד אינו חסין לחלוטין במקרים קיצוניים',['שחוק יסוד בטל כל אימת שנחקק ברוב רגיל','שהכנסת אינה רשאית לחוקק חוקי יסוד','שבית המשפט הופך לרשות מכוננת'],'ביקורת על חוק יסוד מוגבלת למקרים של שימוש לרעה בסמכות המכוננת. אין פירוש הדבר שהכנסת אינה רשאית לחוקק חוקי יסוד או שבית המשפט מחליף אותה.'),
Q('מהו שלב א בבחינת חוקתיות?','בדיקה אם החוק פוגע בזכות חוקתית',['בדיקת התועלת של החוק','בדיקת הסעד','בדיקת הרוב בכנסת'],'השלב הראשון הוא ההגדרה והפגיעה בזכות. הסעד הוא שלב אחרון, ובדיקת הרוב או התועלת אינה מהווה שלב ראשון.'),
Q('איזה משפט מתאר נכון את היחס בין המהפכה לריבונות הכנסת?','הכנסת נותרה מחוקקת ראשית, אך כפופה לחוקי היסוד',['הכנסת איבדה את סמכות החקיקה','הכנסת ריבונית ללא כל מגבלה','בג"ץ מחליף את הכנסת בחקיקה'],'הכנסת ממשיכה לחוקק, אך חוק הפוגע בזכות חייב לעמוד בפסקת ההגבלה. אין היא ריבונית מוחלטת, ואין בג"ץ מחוקק.'),
Q('מהי הבעיה העיקרית שאליה נועדה להשיב תורת הכובעים?','מנין עליונות חוק יסוד אם הוא נחקק כחוק רגיל',['מי ימנה שופטים','כיצד מחשבים רוב','מהו סדר היום של הכנסת'],'בלי הסבר, חוק יסוד נראה כחוק רגיל. תורת הכובעים מסבירה שהוא נחקק בסמכות מכוננת. שלושת המסיחים אינם עוסקים בשאלה זו.'),
]
