EXTRA_E={8: ' הטענה היא שהמהפכה נעשתה בדרך של פסיקה ולא בהליך חוקתי מובהק, ולכן מי שבחר בה לא קיבל לכך מנדט מפורש.', 11: ' ההלכה על הסמכות שינתה את הכללים לכל המקרים העתידיים, ולכן הערך שלה גדול מהתוצאה הקונקרטית בתיק.', 12: ' ההרכב המורחב הוא כלי מקובל לסוגיות חוקתיות עקרוניות, ולכן הוא משקף את חשיבות הנושא ולא מקרה שגרתי.', 16: ' רק אם נמצאה פגיעה בזכות עוברים לבדיקת ההצדקה, ולכן שלב הסעד תמיד אחרון ושלב הרוב אינו חלק מהבחינה הזו.', 17: ' יש להבחין בין ריבונות מוחלטת (שאינה קיימת עוד) לבין סמכות חקיקה שנותרה מלאה בכפוף לחוקי היסוד.', 18: ' התורה נועדה לגשר על הפער בין צורת החקיקה הזהה לבין המעמד השונה, ושאלות על מינוי שופטים או רוב אינן חלק ממנה.'}
for _i,_t in EXTRA_E.items(): QS[_i]['e']+=_t
SUM[-1:-1]=['<h3>2.6 ההשלכות על הרשויות</h3>', '<p>המהפכה לא נגעה רק לכנסת. ס׳ 11 לחוק יסוד: כבוד האדם מחייב כל רשות מרשויות השלטון לכבד את הזכויות שבחוק, ולכן גם החלטות מנהליות נבחנות מול הזכויות. בנוסף נקבע כלל פרשני: חוק נקרא, ככל האפשר, באופן המתיישב עם זכויות היסוד ("פרשנות מקיימת"). במבחן יש להזכיר ששלושת הכלים (פסילה, פרשנות מקיימת, הלכות מנהליות) פועלים יחד.</p>']
QS.append(Q('באיזה חוק יסוד מופיעה פסקת ההתגברות?','חופש העיסוק',['כבוד האדם וחירותו','הכנסת','השפיטה'],'פסקת ההתגברות (ס׳ 8) מופיעה בחוק יסוד: חופש העיסוק בלבד. בחוק כבוד האדם ס׳ 8 הוא דווקא פסקת ההגבלה, ובחוקי הכנסת והשפיטה אין פסקה כזו כלל.'))

